extern unsigned short wfa_defined_debug;

/*
 *  xcCmdProcGetVersion(): process the command get_version string from TM
 *                         to convert it into a internal format
 *  input:        pcmdStr -- a string pointer to the command string
 */
int xcCmdProcGetVersion(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    /* encode the tag without values */
    WFA_ENC_TLV(WFA_GET_VERSION_TLV, 0, NULL, aBuf);
    *aLen = 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 *  xcCmdProcAgentConfig(): process the command traffic_agent_config string
 *                          from TM to convert it into a internal format
 *  input:        pcmdStr -- a string pointer to the command string
 */
int xcCmdProcAgentConfig(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    char *str;
    int i = 0, j=0, kwcnt = 0;
    wfaTLV *hdr = (wfaTLV *)aBuf;
    tgProfile_t tgpf = {0, 0, "", -1, "", -1, 0, 0, 0, TG_WMM_AC_BE, 0, 0};
    tgProfile_t *pf = &tgpf;
    int userPrio = 0;

    DPRINT_IN_FUNC();

    DPRINT_BOX("PARAMS -->>> Traffic Agent config parameters ..." );

    if(aBuf == NULL)
        return WFA_FAILURE;

    while((str = strtok_r(NULL, ",", (char **)&pcmdStr)) != NULL)
    {
        for(i = 0; i<sizeof(keywordStr)/sizeof(typeNameStr_t); i++)
        {
            if(os_strcasecmp(str, keywordStr[i].name) == 0)
            {
                switch(keywordStr[i].type)
                {
                    case KW_PROFILE:
                        str = strtok_r(NULL, ",", (char **)&pcmdStr);
                        if(isString(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect profile keyword format");
                            return WFA_FAILURE;
                        }

                        for(j = 0; j < PROF_LAST; j++)
                        {
                            if(os_strcasecmp(str, profileStr[j].name) == 0)
                            {
                                pf->profile = profileStr[j].type;
                            }
                        }

                        DPRINT_INFO("--> Profile type %i\r\n", pf->profile);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_DIRECTION:
                        str = strtok_r(NULL, ",", (char **)&pcmdStr);
                        if(isString(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect direction keyword format");
                            return WFA_FAILURE;
                        }

                        if(os_strcasecmp(str, "send") == 0)
                        {
                            pf->direction = DIRECT_SEND;
                        }
                        else if(os_strcasecmp(str, "receive") == 0)
                        {
                            pf->direction = DIRECT_RECV;
                        }
                        else
                            printf("Don't know direction\n");

                        DPRINT_INFO("--> Direction %i\r\n", pf->direction);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_DIPADDR: /* dest ip address */
                        memcpy(pf->dipaddr, strtok_r(NULL, ",", &pcmdStr), IPV4_ADDRESS_STRING_LEN);
                        if(isIpV4Addr(pf->dipaddr) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect ipaddr format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> dipaddr %s\r\n", pf->dipaddr);

                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_DPORT:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect port number format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> dport %s\r\n", str);
                        pf->dport = atoi(str);

                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_SIPADDR:
                        memcpy(pf->sipaddr, strtok_r(NULL, ",", &pcmdStr), IPV4_ADDRESS_STRING_LEN);

                        if(isIpV4Addr(pf->sipaddr) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect ipaddr format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> sipaddr %s\r\n", pf->sipaddr);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_SPORT:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect port number format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> sport %s\r\n", str);
                        pf->sport = atoi(str);

                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_FRATE:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect frame rate format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> framerate %s\r\n", str);
                        pf->rate = atoi(str);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_DURATION:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect duration format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> duration %s\r\n", str);
                        pf->duration = atoi(str);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_PLOAD:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect payload format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> payload %s\r\n", str);
                        pf->pksize = atoi(str);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_STARTDELAY:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect startDelay format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> startDelay %s\r\n", str);
                        pf->startdelay = atoi(str);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_MAXCNT:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect max count format");
                            return WFA_FAILURE;
                        }
                        pf->maxcnt = atoi(str);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_TCLASS:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        // if user priority is used, tclass is ignored.
                        if(userPrio == 1)
                            break;

                        if(os_strcasecmp(str, "voice") == 0 ){pf->trafficClass = TG_WMM_AC_VO;}
                        else if(os_strcasecmp(str, "Video") == 0 ){pf->trafficClass = TG_WMM_AC_VI;}
                        else if(os_strcasecmp(str, "Background") == 0 ){pf->trafficClass = TG_WMM_AC_BK;}
                        else if(os_strcasecmp(str, "BestEffort") == 0 ){pf->trafficClass = TG_WMM_AC_BE;}
                        else{pf->trafficClass = TG_WMM_AC_BE;}

                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_USERPRIORITY:
                        str = strtok_r(NULL, ",", &pcmdStr);

                        if( os_strcasecmp(str, "6") == 0 ){pf->trafficClass = TG_WMM_AC_UP6;}
                        else if( os_strcasecmp(str, "7") == 0 ){pf->trafficClass = TG_WMM_AC_UP7;}
                        else if( os_strcasecmp(str, "5") == 0 ){pf->trafficClass = TG_WMM_AC_UP5;}
                        else if( os_strcasecmp(str, "4") == 0 ){pf->trafficClass = TG_WMM_AC_UP4;}
                        else if( os_strcasecmp(str, "1") == 0 ){pf->trafficClass = TG_WMM_AC_UP1;}
                        else if( os_strcasecmp(str, "2") == 0 ){pf->trafficClass = TG_WMM_AC_UP2;}
                        else if( os_strcasecmp(str, "0") == 0 ){pf->trafficClass = TG_WMM_AC_UP0;}
                        else if( os_strcasecmp(str, "3") == 0 ){pf->trafficClass = TG_WMM_AC_UP3;}

                        // if User Priority is used
                        userPrio = 1;

                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_STREAMID:
                        kwcnt++;
                        break;

                    case KW_NUMFRAME:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect numframe format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> num frame %s\r\n", str);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_USESYNCCLOCK:
                        str = strtok_r(NULL, ",", &pcmdStr);
                        if(isNumber(str) == WFA_FAILURE)
                        {
                            DPRINT_ERR("Incorrect sync clock format");
                            return WFA_FAILURE;
                        }
                        DPRINT_INFO("--> sync clock %s\r\n", str);
                        kwcnt++;
                        str = NULL;
                        break;

                    case KW_TAGNAME:
                        str = strtok_r(NULL,",",&pcmdStr);
                        strncpy(pf->WmmpsTagName,str,strlen(str));
                        printf("Got name %s\n",pf->WmmpsTagName);
                        break;

                    case KW_HTI:
                        str = strtok_r(NULL,",",&pcmdStr);
                        if (os_strcasecmp(str, "on") == 0)
                        {
                            pf->hti = 1;
                        }
                        else
                        {
                            pf->hti = 0;
                        }
                        DPRINT_INFO("--> hti %s\r\n", str);
                        break;
                    default:
                        ;
                } /* switch */

                if(str==NULL)
                    break;
            }/* if */
        }/* for */
    }/* while */
    DPRINT_CONTENT("**********************************************************\r\n");
#if 0
    if(kwcnt < 8)
    {
       printf("Incorrect command, missing parameters\n");
       return WFA_FAILURE;
    }
#endif

    printProfile(pf);
    hdr->tag =  WFA_TRAFFIC_AGENT_CONFIG_TLV;
    hdr->len = sizeof(tgProfile_t);

    memcpy(aBuf+4, pf, sizeof(tgpf));
    *aLen = 4+sizeof(tgProfile_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * xcCmdProcAgentSend(): Process and send the Control command
 *                       "traffic_agent_send"
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcAgentSend(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    wfaTLV *hdr = (wfaTLV *)aBuf;
    char *str, *sid;
    int strid;
    int id_cnt = 0;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, 512);

    /* there is only one stream for baseline. Will support
    * multiple streams later.
    */
    str = strtok_r(NULL, ",", &pcmdStr);

    if(str == NULL || str[0] == '\0')
        return WFA_FAILURE;

    /* take the stream ids */
    if(os_strcasecmp(str, "streamid") != 0)
    {
        DPRINT_ERR("Invalid type name");
        return WFA_FAILURE;
    }

    /*
    * To handle there are multiple stream ids such as WMM
    */
    while(1)
    {
        sid = strtok_r (NULL, " ", &pcmdStr);
        if(sid == NULL)
            break;

        if(isNumber(sid) == WFA_FAILURE)
            continue;

        strid = atoi(sid);
        id_cnt++;

        memcpy(aBuf+4*id_cnt, (char *)&strid, 4);
    }

    hdr->tag =  WFA_TRAFFIC_AGENT_SEND_TLV;
    hdr->len = 4*id_cnt;  /* multiple 4s if more streams */

    *aLen = 4 + 4*id_cnt;

#if 1
    {
        int i;
        for(i = 0; i< *aLen; i++)
            printf("%x ", aBuf[i]);

        printf("\n");
    }
#endif

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * xcCmdProcAgentReset(): Process and send the Control command
 *                       "traffic_agent_reset"
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcAgentReset(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    wfaTLV *hdr = (wfaTLV *)aBuf;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    hdr->tag =  WFA_TRAFFIC_AGENT_RESET_TLV;
    hdr->len = 0;  /* multiple 4s if more streams */

    *aLen = 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * xcCmdProcAgentRecvStart(): Process and send the Control command
 *                       "traffic_agent_receive_start"
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcAgentRecvStart(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    wfaTLV *hdr = (wfaTLV *)aBuf;
    char *str, *sid;
    int strid;
    int id_cnt = 0;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    /* there is only one stream for baseline. Will support
     * multiple streams later.
     */
    str = strtok_r(NULL, ",", &pcmdStr);

    if(str == NULL || str[0] == '\0')
    {
        DPRINT_ERR("Null string");
        return WFA_FAILURE;
    }


    if(os_strcasecmp(str, "streamid") != 0)
    {
        DPRINT_ERR("Invalid type name");
        return WFA_FAILURE;
    }

    while(1)
    {
        sid = strtok_r (NULL, " ", &pcmdStr);
        if(sid == NULL)
            break;

        if(isNumber(sid) == WFA_FAILURE)
            continue;

        strid = atoi(sid);
        id_cnt++;

        memcpy(aBuf+4*id_cnt, (char *)&strid, 4);
    }

    hdr->tag =  WFA_TRAFFIC_AGENT_RECV_START_TLV;
    hdr->len = 4*id_cnt;  /* multiple 4s if more streams */

    *aLen = 4 + 4*id_cnt;

#if 1
    {
        int i;
        for(i = 0; i< *aLen; i++)
            printf("%x ", aBuf[i]);

        printf("\n");
    }
#endif

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

