int xcCmdProcAgentSendPing(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    wfaTLV *hdr = (wfaTLV *)aBuf;
    tgPingStart_t *staping = (tgPingStart_t *) (aBuf+sizeof(wfaTLV));
    char *str;
    staping->type = 0;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "destination") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(staping->dipaddr, str, 15);
        }
        if(os_strcasecmp(str, "frameSize") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staping->frameSize=atoi(str);
        }
        if(os_strcasecmp(str, "frameRate") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staping->frameRate=atof(str);
        }
        if(os_strcasecmp(str, "duration") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staping->duration=atoi(str);
        }
        if(os_strcasecmp(str, "type") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "udp") == 0)
                staping->type = 1;
            else
                staping->type = 0;
        }
        if(os_strcasecmp(str, "ifname") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(staping->ifname, str, 15);
        }

//        // Used for to differ IPV4 from IPV6
//        if(os_strcasecmp(str, "iptype") == 0)
//        {
//            str = strtok_r(NULL, ",", &pcmdStr);
//            staping->iptype=atoi(str);
//            DPRINT_INFO("iptype %i\r\n", staping->iptype);
//        }

        if(os_strcasecmp(str, "qos") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "vo") == 0)
            {
                staping->qos = TG_WMM_AC_VO;
            }
            else if(os_strcasecmp(str, "vi") == 0)
            {
                staping->qos = TG_WMM_AC_VI;
            }
            else if(os_strcasecmp(str, "be") ==0)
            {
                staping->qos = TG_WMM_AC_BE;
            }
            else if(os_strcasecmp(str, "bk") == 0)
            {
                staping->qos = TG_WMM_AC_BK;
            }
            else
            {
                staping->qos = TG_WMM_AC_BE;
            }
        }
    }

    DPRINT_BOX("PARAMS -->>> Send Ping ..." );
    DPRINT_INFO("--> Ifname: %s\r\n", staping->ifname);
    DPRINT_INFO("--> Destination: %s\r\n", staping->dipaddr);
    DPRINT_INFO("--> Framesize: %i\r\n", staping->frameSize);
    DPRINT_INFO("--> Framerate: %f\r\n", staping->frameRate);
    DPRINT_INFO("--> Duration: %i\r\n", staping->duration);
    DPRINT_CONTENT("***********************************************************\r\n");

    hdr->tag =  WFA_TRAFFIC_SEND_PING_TLV;
    hdr->len = sizeof(tgPingStart_t);

    *aLen = hdr->len + 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int xcCmdProcAgentStopPing(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    wfaTLV *hdr = (wfaTLV *)aBuf;
    char *str;
    tgPingStop_t *stoping = (tgPingStop_t *) (aBuf+sizeof(wfaTLV));

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
     {
         str = strtok_r(NULL, ",", &pcmdStr);

         if(str == NULL || str[0] == '\0')
             break;

         if(os_strcasecmp(str, "rcvResp") == 0)
         {
             str = strtok_r(NULL, ",", &pcmdStr);
             strncpy(stoping->rcvResp, str, 15);
         }

         if(os_strcasecmp(str, "streamID") == 0)
         {
             str = strtok_r(NULL, ",", &pcmdStr);
             stoping->streamid = atoi(str);
         }
     }

    DPRINT_BOX("PARAMS -->>> Stop Ping ...");

    hdr->tag =  WFA_TRAFFIC_STOP_PING_TLV;
    hdr->len = 4+ sizeof(tgPingStop_t);  /* multiple 4s if more streams */

    *aLen = hdr->len+4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

