/*
 * xcCmdProcStaSetIpConfig(): Process and send the Control command
 *                       "sta_set_ip_config"
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcStaSetIpConfig(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    dutCommand_t staSetIpConfig;
    caStaSetIpConfig_t *setip = (caStaSetIpConfig_t *)&staSetIpConfig.cmdsu.ipconfig;
    char *str;

    DPRINT_IN_FUNC();

    memset(&staSetIpConfig, 0, sizeof(staSetIpConfig));

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setip->intf, str, 15);
        }
        else if(os_strcasecmp(str, "dhcp") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setip->isDhcp = atoi(str);
        }
        else if(os_strcasecmp(str, "ip") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setip->ipaddr, str, 15);
        }
        else if(os_strcasecmp(str, "mask") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setip->mask, str, 15);
        }
        else if(os_strcasecmp(str, "defaultGateway") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setip->defGateway, str, 15);
        }
        else if(os_strcasecmp(str, "primary-dns") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setip->pri_dns, str, 15);
        }
        else if(os_strcasecmp(str, "secondary-dns") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setip->sec_dns, str, 15);
        }
        else
        {
            DPRINT_ERR("Invalid command %s",str);
            // return WFA_FAILURE;
        }
    }

    DPRINT_BOX("PARAMS -->>> Prepare IP config parameters ..." );
    DPRINT_INFO("--> Interface = %s\r\n", setip->intf);
    DPRINT_INFO("--> DHCP = %i\r\n", setip->isDhcp);
    DPRINT_INFO("--> IP = %s\r\n", setip->ipaddr);
    DPRINT_INFO("--> MASK = %s\r\n", setip->mask);
    DPRINT_INFO("--> Default Gateway = %s\r\n", setip->defGateway);
    DPRINT_INFO("--> Primary DNS = %s\r\n", setip->pri_dns);
    DPRINT_INFO("--> Secondary DNS = %s\r\n", setip->sec_dns);
    DPRINT_CONTENT("**********************************************************\r\n");

    WFA_ENC_TLV(WFA_STA_SET_IP_CONFIG_TLV, sizeof(staSetIpConfig), (BYTE *)&staSetIpConfig, aBuf);
    *aLen = 4+sizeof(staSetIpConfig);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

