/*
 * xcCmdProcStaSetEncryption(): Process and send the Control command
 *                       "sta_set_encryption"
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcStaSetEncryption(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    caStaSetEncryption_t *setencryp = (caStaSetEncryption_t *) (aBuf+sizeof(wfaTLV));
    char *str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);
    strcpy(setencryp->authType, "OPEN");

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setencryp->intf, str, 15);
        }
        else if(os_strcasecmp(str, "ssid") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setencryp->ssid, str, 64);
        }
        else if(os_strcasecmp(str, "encpType") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "wep") == 0)
               setencryp->encrptype = 1;
            else
               setencryp->encrptype = 0;
        }
        else if(os_strcasecmp(str, "auth") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setencryp->authType, str, 15);
        }
        else if(os_strcasecmp(str, "key1") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setencryp->keys[0], str, 26);
            setencryp->activeKeyIdx = 0;
        }
        else if(os_strcasecmp(str, "key2") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setencryp->keys[1], str, 26);
        }
        else if(os_strcasecmp(str, "key3") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setencryp->keys[2], str, 26);
        }
        else if(os_strcasecmp(str, "key4") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setencryp->keys[3], str, 26);
        }
        else if(os_strcasecmp(str, "activeKey") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setencryp->activeKeyIdx =  atoi(str);
        }
        else
        {
            DPRINT_WARNING("Incorrect Command, check syntax\r\n");
        }
    }

    DPRINT_BOX("PARAMS -->>> Prepare Set encryption parameters ..." );
    DPRINT_INFO("--> Interface = %s \r\n", setencryp->intf);
    DPRINT_INFO("--> SSID =  %s \r\n", setencryp->ssid);
    DPRINT_INFO("--> AuthType = %s \r\n", setencryp->authType);
    DPRINT_INFO("--> EncType = %d \r\n",setencryp->encrptype );
    DPRINT_INFO("--> ActiveKeyIdx = %d \r\n",setencryp->activeKeyIdx );
    DPRINT_INFO("--> Keys1 = %s \r\n", setencryp->keys[0]);
    DPRINT_INFO("--> Keys2 = %s \r\n", setencryp->keys[1]);
    DPRINT_INFO("--> Keys3 = %s \r\n", setencryp->keys[2]);
    DPRINT_INFO("--> Keys4 = %s \r\n", setencryp->keys[3]);
    DPRINT_CONTENT("**********************************************************\r\n");

    WFA_ENC_TLV(WFA_STA_SET_ENCRYPTION_TLV, sizeof(caStaSetEncryption_t), (BYTE *)setencryp, aBuf);
    *aLen = 4+sizeof(caStaSetEncryption_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}
