            if(os_strcasecmp(str, "enable") == 0
                || os_strcasecmp(str, "optional") == 0)
               setencryp->pmf = WFA_ENABLED;
            else if(os_strcasecmp(str, "required") == 0)
               setencryp->pmf = WFA_REQUIRED;
