int xcCmdProcDeviceGetInfo(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    dutCommand_t *dutCmd = (dutCommand_t *) (aBuf+sizeof(wfaTLV));
    caDevInfo_t *dinfo = &dutCmd->cmdsu.dev;
    char *str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    dinfo->fw = 0;
    str = strtok_r(NULL, ",", &pcmdStr);
    if(str != NULL && str[0] != '\0')
    {
       if(os_strcasecmp(str, "firmware") == 0)
       {
           dinfo->fw = 1;
       }
    }

    WFA_ENC_TLV(WFA_DEVICE_GET_INFO_TLV, 0, NULL, aBuf);
    *aLen = 4;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

