/*
 * xcCmdProcStaSetUAPSD(): Process and send the Control command
 *                       "sta_set_uapsd"
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcStaSetUAPSD(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    caStaSetUAPSD_t *setuapsd = (caStaSetUAPSD_t *) (aBuf+sizeof(wfaTLV));
    char *str;
    wfaTLV *hdr = (wfaTLV *)aBuf;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);
    setuapsd->acBE = 0;
    setuapsd->acBK = 0;
    setuapsd->acVI = 0;
    setuapsd->acVO = 0;

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setuapsd->intf, str, 15);
        }
        else if(os_strcasecmp(str, "ssid") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setuapsd->ssid, str, 64);
        }
        else if(os_strcasecmp(str, "maxSP") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setuapsd->maxSPLength = atoi(str);
        }
        else if(os_strcasecmp(str, "acBE") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setuapsd->acBE = atoi(str);
        }
        else if(os_strcasecmp(str, "acBK") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setuapsd->acBK = atoi(str);

        }
        else if(os_strcasecmp(str, "acVI") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setuapsd->acVI = atoi(str);
        }
        else if(os_strcasecmp(str, "acVO") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setuapsd->acVO = atoi(str);
        }
        else if(os_strcasecmp(str, "type") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setuapsd->type = atoi(str);
        }
        else if(os_strcasecmp(str, "peer") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setuapsd->peer, str, 17);
        }
    }

    hdr->tag =  WFA_STA_SET_UAPSD_TLV;
    hdr->len = sizeof(caStaSetUAPSD_t);

    memcpy(aBuf+4, setuapsd, sizeof(caStaSetUAPSD_t));

    *aLen = 4+sizeof(caStaSetUAPSD_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * xcCmdProcStaDebugSet(): Process and send the Control command
 *                       ""
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcStaDebugSet(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    dutCommand_t *debugSet = (dutCommand_t *) (aBuf+sizeof(wfaTLV));
    char *str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "level") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(atoi(str) == WFA_DEBUG_INFO || WFA_DEBUG_WARNING)
            {
                debugSet->cmdsu.dbg.level = atoi(str);
            }
            else
                return WFA_FAILURE;  /* not support */
        }
        else if(os_strcasecmp(str, "enable") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            printf("enable %i\n", atoi(str));
            switch(atoi(str)) /* enable */
            {
            case 1:
               debugSet->cmdsu.dbg.state = 1;
               printf("enable\n");
               break;
            case 0:
               debugSet->cmdsu.dbg.state = 0;
               printf("disable\n");
               break;
            default:
               printf("wrong\n");
               return WFA_FAILURE;  /* command invalid */
            }
         }
    }

    WFA_ENC_TLV(WFA_STA_DEBUG_SET_TLV, sizeof(dutCommand_t), (BYTE *)debugSet, aBuf);
    *aLen = 4 + sizeof(dutCommand_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

/*
 * xcCmdProcStaSetMode(): Process and send the Control command
 *                       "sta_set_mode"
 * input - pcmdStr  parameter string pointer
 * return - WFA_SUCCESS or WFA_FAILURE;
 */
int xcCmdProcStaSetMode(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    caStaSetMode_t *setmode = (caStaSetMode_t *) (aBuf+sizeof(wfaTLV));
    char *str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        DPRINT_INFO("str = %s\r\n", str);

        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setmode->intf, str, 15);
        }
        else if(os_strcasecmp(str, "ssid") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setmode->ssid, str, 32);
        }
         else if(os_strcasecmp(str, "mode") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(setmode->mode, str,32);
        }
        else if(os_strcasecmp(str, "encpType") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setmode->encrptype = ENCRYPT_NONE;
        }
        else if(os_strcasecmp(str, "channel") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setmode->channel = atoi(str);
        }
        else if(os_strcasecmp(str, "key1") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setmode->keys[0], str, 26);
            setmode->activeKeyIdx = 0;
        }
        else if(os_strcasecmp(str, "key2") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setmode->keys[1], str, 26);
        }
        else if(os_strcasecmp(str, "key3") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setmode->keys[2], str, 26);
        }
        else if(os_strcasecmp(str, "key4") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy((char *)setmode->keys[3], str, 26);
        }
        else if(os_strcasecmp(str, "activeKey") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            setmode->activeKeyIdx =  atoi(str);
        }
        else
        {
            DPRINT_INFO("->Stop: unknown parameter or last parameter\r\n" );
            break;
        }
    }

    DPRINT_BOX("PARAMS -->>> Prepare STA SET MODE parameters ...");
    DPRINT_INFO("--> Interface =  %s\r\n", setmode->intf);
    DPRINT_INFO("--> Mode =  %s\r\n", setmode->mode);
    DPRINT_INFO("--> SSID =  %s\r\n", setmode->ssid);
    DPRINT_INFO("--> Channel =  %i\r\n", setmode->channel);
    DPRINT_INFO("--> EncType = %i\r\n",setmode->encrptype );
    DPRINT_INFO("--> ActiveKeyIdx = %i\r\n",setmode->activeKeyIdx );
    DPRINT_INFO("--> Keys1 = %s\r\n", setmode->keys[0]);
    DPRINT_INFO("--> Keys2 = %s\r\n", setmode->keys[1]);
    DPRINT_INFO("--> Keys3 = %s\r\n", setmode->keys[2]);
    DPRINT_INFO("--> Keys4 = %s\r\n", setmode->keys[3]);
    DPRINT_CONTENT("**********************************************************\r\n");

    WFA_ENC_TLV(WFA_STA_SET_MODE_TLV, sizeof(caStaSetMode_t), (BYTE *)setmode, aBuf);
    *aLen = 4+sizeof(caStaSetMode_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}


