int xcCmdProcStaPresetTestParameters(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    caStaPresetParameters_t *presetTestParams = (caStaPresetParameters_t *) (aBuf+sizeof(wfaTLV));
    char *str;

    DPRINT_IN_FUNC();

    //reset all parameters /Default Values/
    DPRINT_BOX("Reset all DRV parameters to Default Values ..." );
    wfa_dut_param_set_default();

    // Only used for enhanced features functions
#ifdef EXTRA_FEAT
    char *tstr1, *tstr2;
#endif

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);
    memset(presetTestParams, 0, sizeof(caStaPresetParameters_t));

    //Default values
    strncpy(presetTestParams->program_str, "11n", 9);
    strncpy(presetTestParams->mode_str, "Default", 9);
    strncpy(presetTestParams->ht_str, "Default", 9);
    strncpy(presetTestParams->wfa_supplicant_name, "Default", 9);
    strncpy(presetTestParams->fragThreshold_str, "Default", 9);
    strncpy(presetTestParams->rtsThreshold_str, "Default", 9);
    strncpy(presetTestParams->preamble_str, "Default", 9);
    strncpy(presetTestParams->wmm_str, "Default", 9);
    strncpy(presetTestParams->powersave_str, "Default", 9);
    strncpy(presetTestParams->autoconnect_str, "Default", 9);
    strncpy(presetTestParams->reset_str, "Default", 9);
    strncpy(presetTestParams->ftoa_str, "Default", 9);
    strncpy(presetTestParams->ftds_str, "Default", 9);
    strncpy(presetTestParams->activescan_str, "Default", 9);
    strncpy(presetTestParams->tdls_str, "Default", 9);
    strncpy(presetTestParams->tdlsMode_str, "Default", 9);
    strncpy(presetTestParams->roaming_str, "Default", 9);

    for(;;)
    {
        str = strtok_r(pcmdStr, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(presetTestParams->intf, str, 15);
        }
        else if(os_strcasecmp(str, "mode") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);

            if(os_strcasecmp(str, "11b") == 0 || os_strcasecmp(str, "b") == 0)
                presetTestParams->wirelessMode = eModeB;
            else if(os_strcasecmp(str, "11g") == 0 || os_strcasecmp(str, "g") == 0 || os_strcasecmp(str, "bg") ==0 )
                presetTestParams->wirelessMode = eModeBG;
            else if(os_strcasecmp(str, "11a") == 0 || os_strcasecmp(str, "a") == 0)
                presetTestParams->wirelessMode = eModeA;
            else if(os_strcasecmp(str, "11abg") == 0 || os_strcasecmp(str, "abg") == 0)
                presetTestParams->wirelessMode = eModeABG;
            else if(os_strcasecmp(str, "11na") == 0)
                presetTestParams->wirelessMode = eModeAN;
            else if(os_strcasecmp(str, "11ng") == 0)
                presetTestParams->wirelessMode = eModeGN;
            else if(os_strcasecmp(str, "11nl") == 0)
                presetTestParams->wirelessMode = eModeNL;   // n+abg
            else if(os_strcasecmp(str, "11ac") == 0)
                presetTestParams->wirelessMode = eModeAC;

            strncpy(presetTestParams->mode_str, str, 9);
            presetTestParams->modeFlag = 1;

        }
        else if(os_strcasecmp(str, "powersave") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);

            if(os_strcasecmp(str, "off") == 0)
            {
                PARAM_COMMON(ps_on) = 0;
                presetTestParams->legacyPowerSave = 0;
            }
            else
            {
                PARAM_COMMON(ps_on) = 1;
                presetTestParams->legacyPowerSave = 1;
            }
            presetTestParams->psFlag = 1;
            strncpy(presetTestParams->powersave_str, str, 9);
        }
        else if(os_strcasecmp(str, "wmm") == 0)
        {
            presetTestParams->wmmFlag = 1;
            str = strtok_r(NULL, ",", &pcmdStr);

            if(os_strcasecmp(str, "on") == 0)
                presetTestParams->wmmState = 1;
            else if(os_strcasecmp(str, "off") == 0)
                presetTestParams->wmmState = 0;

            strncpy(presetTestParams->wmm_str, str, 9);
        }
        else if(os_strcasecmp(str, "noack") == 0)
        {
            /* NOT USED */
        }
        else if(os_strcasecmp(str, "ht") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "on") == 0)
            {
                presetTestParams->ht = 1;
            }
            else
            {
                presetTestParams->ht = 0;
            }
            strncpy(presetTestParams->ht_str, str, 9);
        }
        else if(os_strcasecmp(str, "RTS") == 0)
        {
            presetTestParams->rtsFlag =1;

            str = strtok_r(NULL, ",", &pcmdStr);
            presetTestParams->rtsThreshold = atoi(str);
            strncpy(presetTestParams->rtsThreshold_str, str, 9);
        }
        else if(os_strcasecmp(str, "FRGMNT") == 0)
        {
            presetTestParams->fragFlag =1;

            str = strtok_r(NULL, ",", &pcmdStr);
            presetTestParams->fragThreshold = atoi(str);
            strncpy(presetTestParams->fragThreshold_str, str, 9);
        }
        else if(os_strcasecmp(str, "autoconnect") == 0)
        {
            presetTestParams->autoCFlag =1;

            str = strtok_r(NULL, ",", &pcmdStr);
            presetTestParams->autoconnect= atoi(str);

            strncpy(presetTestParams->autoconnect_str, str, 9);
        }
        else if(os_strcasecmp(str, "preamble") == 0)
        {
            presetTestParams->preambleFlag =1;
            str = strtok_r(NULL, ",", &pcmdStr);

            if(os_strcasecmp(str, "long") == 0)
                presetTestParams->preamble = eLong;
            else
                presetTestParams->preamble = eShort;

            strncpy(presetTestParams->preamble_str, str, 9);
        }
        else if(os_strcasecmp(str, "supplicant") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "WPA_Supplicant") == 0)
            {
                presetTestParams->supplicant=eWpaSupplicant;
                strncpy(presetTestParams->wfa_supplicant_name, str, 100);
            }

            else if(os_strcasecmp(str, "Default") == 0)
            {
                presetTestParams->supplicant=eDefault;
                strncpy(presetTestParams->wfa_supplicant_name, str, 100);
            }
            else
            {
                presetTestParams->supplicant=eWpaSupplicant;
                strncpy(presetTestParams->wfa_supplicant_name, str, 100);
            }
        }
        else if(os_strcasecmp(str, "reset") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "11n") == 0)
            {
                presetTestParams->reset = eResetProg11n;
            }
            strncpy(presetTestParams->reset_str, str, 9);
        }
        else if (os_strcasecmp(str, "program") == 0)
        {
            presetTestParams->programFlag= 1;
            str = strtok_r(NULL, ",", &pcmdStr);
            if (os_strcasecmp(str, "PMF") == 0)
            {
                presetTestParams->program=PROG_TYPE_PMF;
            }
            else if (os_strcasecmp(str, "General") == 0)
            {
                presetTestParams->program=PROG_TYPE_GEN;
            }
            else if (os_strcasecmp(str, "TDLS") == 0)
            {
                presetTestParams->program=PROG_TYPE_TDLS;
            }
            else if (os_strcasecmp(str, "VOE") == 0)
            {
                presetTestParams->program=PROG_TYPE_VENT;
            }
            else if (os_strcasecmp(str, "WFD") == 0)
            {
                presetTestParams->program=PROG_TYPE_WFD;
            }
            else if (os_strcasecmp(str, "MBO") == 0)
            {
                presetTestParams->program=PROG_TYPE_MBO;
            }
            else
            {
                presetTestParams->program=PROG_TYPE_GEN;
            }
            strncpy(presetTestParams->program_str, str, 9);
        }
        else if(os_strcasecmp(str, "ft_oa") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "Enable") == 0)
            {
                presetTestParams->ftoa = eEnable;
            }
            else
            {
                presetTestParams->ftoa = eDisable;
            }
            strncpy(presetTestParams->ftoa_str, str, 9);
        }
        else if(os_strcasecmp(str, "ft_ds") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "Enable") == 0)
            {
                presetTestParams->ftds = eEnable;
            }
            else
            {
                presetTestParams->ftds = eDisable;
            }
            strncpy(presetTestParams->ftds_str, str, 9);
        }
        else if(os_strcasecmp(str, "active_scan") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "Enable") == 0)
            {
                presetTestParams->activescan = eEnable;
            }
            else
            {
                presetTestParams->activescan = eDisable;
            }
            strncpy(presetTestParams->activescan_str, str, 9);
        }
        //MBO
        else if(os_strcasecmp(str, "Ch_Pref_Num") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            presetTestParams->Ch_Pref_Num = atoi(str);
        }
        else if(os_strcasecmp(str, "Ch_Pref") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "Clear") == 0){
                presetTestParams->Ch_Pref = 0;
            }else{
                presetTestParams->Ch_Pref = atoi(str);
            }
            presetTestParams->Ch_Pref_Flag=1;
        }
        else if(os_strcasecmp(str, "Ch_Op_Class") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            presetTestParams->Ch_Op_Class = atoi(str);
        }
        else if(os_strcasecmp(str, "Ch_Reason_Code") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            presetTestParams->Ch_Reason_Code = atoi(str);
        }
        else if(os_strcasecmp(str, "Roaming") == 0)
        {
            presetTestParams->roamingFlag= 1;
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "Enabled") == 0)
            {
                presetTestParams->roaming = 1;
            }
            else if(os_strcasecmp(str, "Disabled") == 0)
            {
                presetTestParams->roaming = 0;
            }
            else if(os_strcasecmp(str, "Disable") == 0)
            {
                presetTestParams->roaming = 0;
            }
            else
            {
                presetTestParams->roaming = roaming_mbo_flag;
            }
            strncpy(presetTestParams->roaming_str, str, 9);
        }
        else if(os_strcasecmp(str, "tdls") == 0)
        {
            presetTestParams->tdlsFlag= 1;
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "Enabled") == 0)
            {
                presetTestParams->tdls = eEnable;
            }
            else
            {
                presetTestParams->tdls = eDisable;
            }
            strncpy(presetTestParams->tdls_str, str, 9);
        }
        else if(os_strcasecmp(str, "tdlsmode") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "Default") == 0)
            {
                presetTestParams->tdlsMode = eDef;
            }
            else if(os_strcasecmp(str, "HiLoMac") == 0)
            {
                presetTestParams->tdlsMode = eHiLoMac;
            }
            else if(os_strcasecmp(str, "ExistLink") == 0)
            {
                presetTestParams->tdlsMode = eExistLink;
            }
            else if(os_strcasecmp(str, "APProhibit") == 0)
            {
                presetTestParams->tdlsMode = eAPProhibit;
            }
            else if(os_strcasecmp(str, "WeakSecurity") == 0)
            {
                presetTestParams->tdlsMode = eWeakSec;
            }
            else if(os_strcasecmp(str, "IgnoreChswitchProhibit") == 0)
            {
                presetTestParams->tdlsMode = eIgnChnlSWProh;
            }
            strncpy(presetTestParams->tdlsMode_str, str, 9);
        }


    }

    DPRINT_BOX("PARAMS -->>> Preparing STAUT config parameters ..." );
    DPRINT_INFO("--> INTERFACE = %s\r\n" ,presetTestParams->intf);
    DPRINT_INFO("--> PROGRAM = %s\r\n" ,presetTestParams->program_str);
    DPRINT_INFO("--> MODE = %s\r\n" ,presetTestParams->mode_str);
    DPRINT_INFO("--> HT = %s\r\n" ,presetTestParams->ht_str);
    DPRINT_INFO("--> SUPPLICANT = %s\r\n" ,presetTestParams->wfa_supplicant_name);
    DPRINT_INFO("--> FRGMNT = %s\r\n" ,presetTestParams->fragThreshold_str);
    DPRINT_INFO("--> RTS = %s\r\n" ,presetTestParams->rtsThreshold_str);
    DPRINT_INFO("--> PREAMBLE = %s\r\n" ,presetTestParams->preamble_str);
    DPRINT_INFO("--> WMM = %s\r\n" ,presetTestParams->wmm_str);
    DPRINT_INFO("--> POWERSAVE = %s\r\n" ,presetTestParams->powersave_str);
    DPRINT_INFO("--> AUTO CONNECT = %s\r\n" ,presetTestParams->autoconnect_str);
    DPRINT_INFO("--> RESET = %s\r\n" ,presetTestParams->reset_str);
    DPRINT_INFO("--> FT_OA = %s\r\n" ,presetTestParams->ftoa_str);
    DPRINT_INFO("--> FT_DS = %s\r\n" ,presetTestParams->ftds_str);
    DPRINT_INFO("--> ACTIVE SCAN = %s\r\n" ,presetTestParams->activescan_str);
    DPRINT_INFO("--> TDLS = %s\r\n" ,presetTestParams->tdls_str);
    DPRINT_INFO("--> TDLS MODE = %s\r\n" ,presetTestParams->tdlsMode_str);
    DPRINT_INFO("--> ROAMING = %s\r\n" ,presetTestParams->roaming_str);
    DPRINT_CONTENT("***********************************************************\r\n");

    presetTestParams->uapsd_flag = PARAM_COMMON(uapsd_queues);
    presetTestParams->uapsd_t_flag = PARAM_COMMON(uapsd_timeout);
    presetTestParams->ps_flag = PARAM_COMMON(ps_on);
    presetTestParams->ampdu_flag = ampdu_flag;
    presetTestParams->gf_flag = PARAM_FEATS(gf);
    presetTestParams->sgi_flag = PARAM_COMMON(sgi);
    presetTestParams->NoIdle = noidle;
    presetTestParams->pmf_flag = PARAM_FEATS(pmf);

    WFA_ENC_TLV(WFA_STA_PRESET_PARAMETERS_TLV, sizeof(caStaPresetParameters_t), (BYTE *)presetTestParams, aBuf);
    *aLen = 4 + sizeof(caStaPresetParameters_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int xcCmdProcStaSendTCP(char *pcmdStr, BYTE *aBuf, int *aLen)
 {
    SendTCP_t *staTCP = (SendTCP_t *) (aBuf+sizeof(wfaTLV));
    char *str;
    staTCP->type = 0;
    staTCP->port = 5006;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
       return WFA_FAILURE;

     memset(aBuf, 0, *aLen);

        for(;;)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(str == NULL || str[0] == '\0')
                break;

            if(os_strcasecmp(str, "destination") == 0)
            {
                str = strtok_r(NULL, ",", &pcmdStr);
                strncpy(staTCP->dipaddr, str, 15);
                DPRINT_INFO("destination %s\r\n", staTCP->dipaddr);
            }
            if(os_strcasecmp(str, "frameSize") == 0)
            {
                str = strtok_r(NULL, ",", &pcmdStr);
                staTCP->frameSize=atoi(str);
                DPRINT_INFO("framesize %i\r\n", staTCP->frameSize);
            }
            if(os_strcasecmp(str, "duration") == 0)
            {
                str = strtok_r(NULL, ",", &pcmdStr);
                staTCP->duration=atoi(str);
                DPRINT_INFO("duration %i\r\n", staTCP->duration);
            }
            if(os_strcasecmp(str, "NumStream") == 0)
            {
                str = strtok_r(NULL, ",", &pcmdStr);
                staTCP->NumStream=atoi(str);
                DPRINT_INFO("NumStream %i\r\n", staTCP->NumStream);
            }

            if(os_strcasecmp(str, "port") == 0)
            {
                str = strtok_r(NULL, ",", &pcmdStr);
                staTCP->port=atoi(str);
                DPRINT_INFO("port %d\r\n", staTCP->port);
            }

            if(os_strcasecmp(str, "type") == 0)
             {
                 str = strtok_r(NULL, ",", &pcmdStr);
                 if(os_strcasecmp(str, "udp") == 0)
                     staTCP->type = 1;
                 else
                     staTCP->type = 0;
             }

        }

        WFA_ENC_TLV(WFA_STA_SENDTCP_TLV, sizeof(SendTCP_t), (BYTE *)staTCP, aBuf);
        *aLen = 4 + sizeof(SendTCP_t);

        DPRINT_OUT_FUNC();

        return WFA_SUCCESS;
 }

int xcCmdProcStaRcvTCP(char *pcmdStr, BYTE *aBuf, int *aLen)
 {
    int portNumber=5006;
    char *str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "port") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            portNumber = atoi(str);
            DPRINT_INFO("port %d\r\n", portNumber);
        }

    }

    WFA_ENC_TLV(WFA_STA_RCVTCP_TLV, 8,(BYTE *)&portNumber, aBuf);
    *aLen = 12;

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

