int xcCmdProcStaSendNeigReq(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    char *str;
    dutCommand_t *getInfo = (dutCommand_t *) (aBuf+sizeof(wfaTLV));

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    str = strtok_r(NULL, ",", &pcmdStr);
    if(str == NULL || str[0] == '\0')
        return WFA_FAILURE;

    if(os_strcasecmp(str, "interface") == 0)
    {
       str = strtok_r(NULL, ",", &pcmdStr);
       strncpy(getInfo->intf, str, 15);
       DPRINT_INFO("interface %s\r\n", getInfo->intf);
    }

    WFA_ENC_TLV(WFA_STA_SEND_NEIGREQ_TLV, sizeof(dutCommand_t), (BYTE *)getInfo, aBuf);
    *aLen = 4 + sizeof(dutCommand_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int xcCmdProcStaSetRadio(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    char *str;
    dutCommand_t *cmd = (dutCommand_t *) (aBuf+sizeof(wfaTLV));
    caStaSetRadio_t *sr = &cmd->cmdsu.sr;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(cmd->intf, str, 15);
            DPRINT_INFO("interface %s\r\n", cmd->intf);
        }
        else if (os_strcasecmp(str, "mode") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if (os_strcasecmp(str, "off") == 0)
            {
                sr->mode = WFA_OFF;
            }
            else
            {
                sr->mode = WFA_ON;
            }
        }
    }

    WFA_ENC_TLV(WFA_STA_SET_RADIO_TLV, sizeof(dutCommand_t), (BYTE *)cmd, aBuf);
    *aLen = 4+sizeof(dutCommand_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

int xcCmdProcStaSetWireless(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    caStaSetWireless_t *staWirelessParams = (caStaSetWireless_t *) (aBuf+sizeof(wfaTLV));
    char *str;

    DPRINT_IN_FUNC();

    memset(staWirelessParams, 0, sizeof(*staWirelessParams));

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
        {
            break;
        }

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(staWirelessParams->intf, str, WFA_IF_NAME_LEN);
        }
        else if(os_strcasecmp(str, "txsp_stream") == 0 )
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "1SS") == 0){PARAM_COMMON(nss) = 1;}
            else if(os_strcasecmp(str, "2SS") == 0 ){
                if((PARAM_COMMON_DEF(nss) > 1)){
                    PARAM_COMMON(nss) = 2;
                }else{
                    PARAM_COMMON(nss) = PARAM_COMMON_DEF(nss);
                }
            }
            else if(os_strcasecmp(str, "3SS") == 0 ){
                if((PARAM_COMMON_DEF(nss) > 2)){
                    PARAM_COMMON(nss) = 3;
                }else{
                    PARAM_COMMON(nss) = PARAM_COMMON_DEF(nss);
                }
            }
        }
        else if(os_strcasecmp(str, "rxsp_stream") == 0 )
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "1SS") == 0){PARAM_COMMON(nss) = 1;}
            else if(os_strcasecmp(str, "2SS") == 0 ){
                if((PARAM_COMMON_DEF(nss) > 1)){
                    PARAM_COMMON(nss) = 2;
                }else{
                    PARAM_COMMON(nss) = PARAM_COMMON_DEF(nss);
                }
            }
            else if(os_strcasecmp(str, "3SS") == 0 ){
                if((PARAM_COMMON_DEF(nss) > 2)){
                    PARAM_COMMON(nss) = 3;
                }else{
                    PARAM_COMMON(nss) = PARAM_COMMON_DEF(nss);
                }
            }
        }
        else if(os_strcasecmp(str, "LDPC") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if((os_strcasecmp(str, "enable") == 0) && (PARAM_COMMON_DEF(ldpc_on)==1))
            {
                PARAM_COMMON(ldpc_on) = 1;
            }
            else{
                PARAM_COMMON(ldpc_on) = 0;
            }
        }
        else if(os_strcasecmp(str, "program") == 0) // VHT or 11n or Voice
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(staWirelessParams->program, str, WFA_PROGNAME_LEN);
        }
        else if(os_strcasecmp(str, "ampdu") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "enable") == 0)
            {
                ampdu_flag = 1;
            }
            else if(os_strcasecmp(str, "disable") == 0)
            {
                ampdu_flag = 0;
            }
        }
        else if(os_strcasecmp(str, "amsdu") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "enable") == 0)
            {
                amsdu_flag = 1;
            }
            else if(os_strcasecmp(str, "disable") == 0)
            {
                amsdu_flag = 0;
            }
        }
        else if(os_strcasecmp(str, "OFDMA") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if((os_strcasecmp(str, "UL") == 0) && (PARAM_COMMON_DEF(he_ul_on)==1))
            {
                staWirelessParams->he_ul_on = 1;
                PARAM_COMMON(he_ul_on)=1;
            }else{
                staWirelessParams->he_ul_on = 0;
                PARAM_COMMON(he_ul_on)=0;
            }
            he_ul_on_en = 1;
        }
        else if(os_strcasecmp(str, "BCC") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if((os_strcasecmp(str, "enable") == 0) && (PARAM_COMMON_DEF(ldpc_on)==1))
            {
                PARAM_COMMON(ldpc_on) = 0;
            }
            else{
                PARAM_COMMON(ldpc_on) = 1;
            }
        }
        else if(os_strcasecmp(str, "mcs_fixedrate") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staWirelessParams->mcs_fixedrate = atoi(str);
        }
        else if(os_strcasecmp(str, "sgi20") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if((os_strcasecmp(str, "enable") == 0) && (PARAM_COMMON_DEF(sgi)==1))
            {
                if((PARAM_COMMON_DEF(sgi) == 1) && ((DUT_WIDTH == 40) || (DUT_WIDTH == 80)))
                {
                    PARAM_COMMON(sgi) = 1;
                }
                else
                {
                    PARAM_COMMON(sgi) = 0;
                    PARAM_COMMON(sgi80) = 0;
                }
            }
            else
            {
                PARAM_COMMON(sgi) = 0;
                PARAM_COMMON(sgi80) = 0;
            }
        }
        else if(os_strcasecmp(str, "sgi40") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if((os_strcasecmp(str, "enable") == 0) && (PARAM_COMMON_DEF(sgi)==1))
            {
                if((PARAM_COMMON_DEF(sgi) == 1) && ((DUT_WIDTH == 40) || (DUT_WIDTH == 80)))
                {
                    PARAM_COMMON(sgi) = 1;
                }
                else
                {
                    PARAM_COMMON(sgi) = 0;
                    PARAM_COMMON(sgi80) = 0;
                }
            }
            else
            {
                PARAM_COMMON(sgi) = 0;
                PARAM_COMMON(sgi80) = 0;
            }
        }
        else if(os_strcasecmp(str, "sgi80") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if((os_strcasecmp(str, "enable") == 0) && (PARAM_COMMON_DEF(sgi80)==1))
            {
                if((PARAM_COMMON_DEF(sgi80) == 1) && (DUT_WIDTH == 80))
                {
                    DPRINT_INFO("--> SGI80 on\r\n");
                    PARAM_COMMON(sgi80) = 1;
                }
                else
                {
                    DPRINT_INFO("--> SGI80 off\r\n");
                    DPRINT_INFO("--> DUT_WIDTH %d\r\n", DUT_WIDTH);
                    PARAM_COMMON(sgi80) = 0;
                }
            }
            else
            {
                PARAM_COMMON(sgi80) = 0;
            }
        }
    }

    //HE UL
    if(he_ul_on_en==1){
        staWirelessParams->he_ul_on = PARAM_COMMON(he_ul_on);
    }else{
        staWirelessParams->he_ul_on = PARAM_COMMON_DEF(he_ul_on);
    }

    DPRINT_BOX("PARAMS -->>> Preparing STAUT config parameters ...");
    DPRINT_INFO("--> PROGRAM = %s\r\n" ,staWirelessParams->program);
    DPRINT_INFO("--> INTERFACE = %s\r\n" ,staWirelessParams->intf);
    DPRINT_INFO("--> NSS = %d\r\n" ,PARAM_COMMON(nss));
    DPRINT_INFO("--> MCS FIXED = %d\r\n" ,  staWirelessParams->mcs_fixedrate);
    DPRINT_INFO("--> AMPDU = %d\r\n" ,ampdu_flag);
    DPRINT_INFO("--> AMSDU = %d\r\n" ,amsdu_flag);
    DPRINT_INFO("--> LDPC = %d\r\n" , PARAM_COMMON(ldpc_on));
    DPRINT_INFO("--> SGI20 = %d\r\n" ,PARAM_COMMON(sgi));
    DPRINT_INFO("--> SGI40 = %d\r\n" ,PARAM_COMMON(sgi));
    DPRINT_INFO("--> SGI80 = %d\r\n" ,PARAM_COMMON(sgi80));
    DPRINT_INFO("--> HE UL = %d\r\n" ,staWirelessParams->he_ul_on);
    DPRINT_CONTENT("**********************************************************\r\n");

    WFA_ENC_TLV(WFA_STA_SET_WIRELESS_TLV, sizeof(caStaSetWireless_t), (BYTE *)staWirelessParams, aBuf);
    *aLen = 4+sizeof(caStaSetWireless_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

