int xcCmdProcStaSetRFeature(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    dutCommand_t *dutcmd = (dutCommand_t *) (aBuf+sizeof(wfaTLV));
    caStaRFeat_t *rfeat = (caStaRFeat_t *) &dutcmd->cmdsu.rfeat;
    char *str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    DPRINT_BOX("PARAMS -->>> Preparing STAUT RFeature parameters ...");
    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(dutcmd->intf, str, 15);
        }
        else if(os_strcasecmp(str, "prog") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeat->prog, str, 8);
        }
        else if(os_strcasecmp(str, "uapsd") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "enable") == 0)
                rfeat->uapsd = eEnable;
            else
                rfeat->uapsd = eDisable;
        }
        else if(os_strcasecmp(str, "peer") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeat->peer, str, 17);
        }
        else if(os_strcasecmp(str, "ChSwitchMode") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeat->ChSwitchMode, str, 10);
        }
        else if(os_strcasecmp(str, "OffChNum") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->OffChNum = atoi(str);
            if(rfeat->OffChNum==44)
            {
                rfeat->OffChFreq=5220;
            }
            else if(rfeat->OffChNum==36)
            {
                rfeat->OffChFreq=5180;
            }
            else if(rfeat->OffChNum==46)
            {
                rfeat->OffChFreq=5230;
            }
            else if(rfeat->OffChNum==11)
            {
                rfeat->OffChFreq=2462;
            }
        }
        else if(os_strcasecmp(str, "SecChOffset") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeat->sec_channel_offset, str, 10);
        }
        else if(os_strcasecmp(str, "tpktimer") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            if(os_strcasecmp(str, "enable") == 0)
                rfeat->tpktimer= eEnable;
            else
                rfeat->tpktimer = eDisable;
        }
        //MBO
        else if(os_strcasecmp(str, "Ch_Pref_Num") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->Ch_Pref_Num = atoi(str);
        }
        else if(os_strcasecmp(str, "Ch_Pref") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->Ch_Pref_flag=1;
            if(os_strcasecmp(str, "Clear") == 0){
                rfeat->Ch_Pref = 3;
            }else{
                rfeat->Ch_Pref = atoi(str);
            }
        }
        else if(os_strcasecmp(str, "Ch_Op_Class") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->Ch_Op_Class = atoi(str);
        }
        else if(os_strcasecmp(str, "Ch_Reason_Code") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->Ch_Reason_Code = atoi(str);
        if (0 == rfeat->Ch_Reason_Code)
        {
            Ch_Pref1 = rfeat->Ch_Pref;
            Ch_Reason_Code1 = rfeat->Ch_Reason_Code;
            Ch_Pref_Num1 = rfeat->Ch_Pref_Num;
            Ch_Op_Class1 = rfeat->Ch_Op_Class;
        }
        else
        {
            Ch_Pref2 = rfeat->Ch_Pref;
            Ch_Reason_Code2 = rfeat->Ch_Reason_Code;
            Ch_Pref_Num2 = rfeat->Ch_Pref_Num;
            Ch_Op_Class2 = rfeat->Ch_Op_Class;
        }
        }
        else if(os_strcasecmp(str, "Cellular_Data_Cap") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->Cellular_Data_Cap = atoi(str);
        }
        //HE
        else if(os_strcasecmp(str, "GI") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);

#ifdef __LINUX__
            //GET CURRENT BW (iw dev | grep "width: 80")
            CMD_EXEC("iw dev | grep 'width: 20' > /valid/tmp/tmp_width.txt");

            char ch;
            FILE *f = fopen("/valid/tmp/tmp_width.txt", "r+");

            if(fscanf(f,"%c",&ch)==EOF)
            {
                if(os_strcasecmp(str, "0.8") == 0){rfeat->mcs_fixedrate_id=874;}
                else if(os_strcasecmp(str, "1.6") == 0){rfeat->mcs_fixedrate_id=875;}
                else if(os_strcasecmp(str, "3.2") == 0){rfeat->mcs_fixedrate_id=876;}
                else{rfeat->mcs_fixedrate_id=875;}
            }else{
                if(os_strcasecmp(str, "0.8") == 0){rfeat->mcs_fixedrate_id=868;}
                else if(os_strcasecmp(str, "1.6") == 0){rfeat->mcs_fixedrate_id=869;}
                else if(os_strcasecmp(str, "3.2") == 0){rfeat->mcs_fixedrate_id=870;}
                else{rfeat->mcs_fixedrate_id=869;}
            }
            fclose(f);
#else
            if(os_strcasecmp(str, "0.8") == 0){rfeat->mcs_fixedrate_id=0x2807;}
            else if(os_strcasecmp(str, "1.6") == 0){rfeat->mcs_fixedrate_id=0x2a07;}
            else if(os_strcasecmp(str, "3.2") == 0){rfeat->mcs_fixedrate_id=0x2c07;}
            else{rfeat->mcs_fixedrate_id=0x2a07;}
#endif

            DPRINT_INFO("-->GI = %s \r\n", str);
            DPRINT_INFO("-->MCS ID = %d \r\n", rfeat->mcs_fixedrate_id);
        }
        //TWT
        else if (os_strcasecmp(str, "NDPPagingInd") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            //ignore it
        } else if (os_strcasecmp(str, "RespPMMode") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            //ignore it
        } else if (os_strcasecmp(str, "NegotiationType") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            //ignore it
        } else if (os_strcasecmp(str, "TWT_Setup") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeat->twt.setup, str, 10);
            rfeat->twt.on = 1;
            rfeat->twt.wake_dur_unit = 0;
        } else if (os_strcasecmp(str, "SetupCommand") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->twt.setup_command = atoi(str);
        } else if (os_strcasecmp(str, "TWT_Trigger") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            //ignore it
        } else if (os_strcasecmp(str, "implicit") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            //ignore it
        } else if (os_strcasecmp(str, "FlowType") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->twt.flow_type = atoi(str);
        } else if (os_strcasecmp(str, "WakeIntervalMantissa") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->twt.wake_interval_mantissa = atoi(str);
        } else if (os_strcasecmp(str, "WakeIntervalExp") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->twt.wake_interval_exp = atoi(str);
        } else if (os_strcasecmp(str, "Protection") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            //ignore it
        } else if (os_strcasecmp(str, "NominalMinWakeDur") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->twt.nominal_min_wake_dur = atoi(str);
        } else if (os_strcasecmp(str, "TWT_Channel") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            //ignore it
        } else if (os_strcasecmp(str, "FlowID") == 0) {
            str = strtok_r(NULL, ",", &pcmdStr);
            rfeat->twt.flow_id = atoi(str);
        }
    }
    DPRINT_CONTENT("***********************************************************\r\n");

    WFA_ENC_TLV(WFA_STA_SET_RFEATURE_TLV, sizeof(dutCommand_t), (BYTE *)dutcmd, aBuf);
    *aLen = 4+sizeof(dutCommand_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

