int xcCmdProcStaStartWfdConnection(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    caStaStartWfdConn_t *staStartWfdConn = (caStaStartWfdConn_t *) (aBuf+sizeof(wfaTLV));
    char *str;
    BYTE tmp_cnt;
    char *tmp_str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(pcmdStr, ",", &pcmdStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(staStartWfdConn->intf, str,WFA_IF_NAME_LEN-1);
            staStartWfdConn->intf[WFA_IF_NAME_LEN-1]='\0';
        }
        else if(os_strcasecmp(str, "peeraddress") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);

            for(tmp_cnt=0;;tmp_cnt++)
            {
                tmp_str = strtok_r(str, " ", &str);
                if(str == NULL || str[0] == '\0')
                    break;

                strncpy(staStartWfdConn->peer[tmp_cnt], tmp_str, WFA_P2P_DEVID_LEN);
                staStartWfdConn->peer[tmp_cnt][WFA_P2P_DEVID_LEN-1]='\0';
            }
        }
        else if(os_strcasecmp(str, "init_wfd") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staStartWfdConn->init_wfd= atoi(str);
            staStartWfdConn->init_wfd_flag=1;
        }
        else if(os_strcasecmp(str, "intent_val") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staStartWfdConn->intent_val= atoi(str);
            staStartWfdConn->intent_val_flag=1;
        }
        else if(os_strcasecmp(str, "oper_chn") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staStartWfdConn->oper_chn= atoi(str);
            staStartWfdConn->oper_chn_flag=1;
        }
        else if(os_strcasecmp(str, "coupledSession") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);
            staStartWfdConn->coupledSession= atoi(str);
            staStartWfdConn->coupledSession_flag=1;
        }
    }

    WFA_ENC_TLV(WFA_STA_START_WFD_CONNECTION_TLV,sizeof(caStaStartWfdConn_t), (BYTE *)staStartWfdConn, aBuf);
    *aLen = 4+sizeof(caStaStartWfdConn_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

