int xcCmdProcAPGetMacAddress(char *pcmStr, BYTE *aBuf, int *aLen)
{
    caAp11n_t* apWirelessParams = (caAp11n_t *) (aBuf+sizeof(wfaTLV));
    char * str;

    DPRINT_IN_FUNC();

    //##################################################################################################################
    //PARSSING UCC COMMAND: ap_set_wireless
    //##################################################################################################################
    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmStr);

        if(str == NULL || str[0] == '\0')
        {
            break;
        }

        if(os_strcasecmp(str, "interface") == 0)
        {
            str = strtok_r(NULL, ",", &pcmStr);
            DPRINT_INFO("#_INFO_#:interface param is not taken into account for DUT \r\n" );
        }

        else if(os_strcasecmp(str, "WLAN_TAG") == 0)
        {
            str = strtok_r(NULL, ",", &pcmStr);
            apWirelessParams->wlan_tag = atoi(str);
        }
    }
    //##################################################################################################################
    // END PARSING PARAMS
    //##################################################################################################################

    WFA_ENC_TLV(WFA_AP_GET_MAC_ADDRESS_TLV, sizeof(caAp11n_t), (BYTE *)apWirelessParams, aBuf);
    *aLen = 4+sizeof(caAp11n_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

