int xcCmdProcAPResetDefault(char *pcmStr, BYTE *aBuf, int *aLen)
{
    caAPResetDefault_t *ResetDefault = (caAPResetDefault_t *) (aBuf+sizeof(wfaTLV));
    char *str;

    DPRINT_IN_FUNC();

    if(aBuf == NULL)
        return WFA_FAILURE;

    memset(aBuf, 0, *aLen);

    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmStr);
        if(str == NULL || str[0] == '\0')
            break;

        if(os_strcasecmp(str, "NAME") == 0)
        {
            str = strtok_r(NULL, ",", &pcmStr);
            strncpy(ResetDefault->intf, str, 15);
            DPRINT_INFO("--> INTERFACE = %s\r\n" ,str);
        }
        else if(os_strcasecmp(str, "program") == 0)
        {
            str = strtok_r(NULL, ",", &pcmStr);
            strncpy(ResetDefault->prog, str, 8);
            DPRINT_INFO("--> PROGRAM = %s\r\n" ,str);
        }
        else if(os_strcasecmp(str, "type") == 0)
        {
            str = strtok_r(NULL, ",", &pcmStr);
            strncpy(ResetDefault->type, str, 12);
            DPRINT_INFO("--> TYPE = %s\r\n" ,str);
        }
        else
        {
            DPRINT_WARNING("Incorrect Command, check syntax\r\n");
        }
    }

    //reset all parameters /Default Values/
    DPRINT_BOX("Reset all DRV parameters to Default Values ..." );
    wfa_dut_param_set_default();

    WFA_ENC_TLV(WFA_AP_RESET_DEFAULT_TLV, sizeof(caAPResetDefault_t), (BYTE *)ResetDefault, aBuf);
    *aLen = 4+sizeof(caAPResetDefault_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}

