int xcCmdProcAPSetRFeature(char *pcmdStr, BYTE *aBuf, int *aLen)
{
    caApRFeat_t *rfeatap = (caApRFeat_t *) (aBuf+sizeof(wfaTLV));
    char *str;

    DPRINT_IN_FUNC();

    DPRINT_BOX("PARAMS -->>> Preparing APUT RFeature parameters ...");
    for(;;)
    {
        str = strtok_r(NULL, ",", &pcmdStr);

        if(str == NULL || str[0] == '\0')
        {
            break;
        }

        if(os_strcasecmp(str, "NAME") == 0)
        {
            DPRINT_INFO("Interface --> %s  \r\n",str);
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeatap->intf, str, 15);
        }
        else if(os_strcasecmp(str, "type") == 0)
        {
            DPRINT_INFO("Type --> %s  \r\n",str);
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeatap->prog, str, 8);
        }
        else if(os_strcasecmp(str, "Chnum_band") == 0)
        {
            DPRINT_INFO("Chnum_band --> %s  \r\n",str);
            str = strtok_r(NULL, ",", &pcmdStr);
            strncpy(rfeatap->Chnum_band, str, 10);
        }

        //##############################
        // WIFI 6 / HE
        //##############################

        //LTF (6.4,12.8)

        //GI (0.8/1.6/3.2)
        else if(os_strcasecmp(str, "GI") == 0)
        {
            str = strtok_r(NULL, ",", &pcmdStr);

            if(os_strcasecmp(str, "0.8") == 0)
            {
                rfeatap->mcs_fixedrate_id=868;
            }
            else if(os_strcasecmp(str, "1.6") == 0)
            {
                rfeatap->mcs_fixedrate_id=869;
            }
            else if(os_strcasecmp(str, "3.2") == 0)
            {
                rfeatap->mcs_fixedrate_id=870;
            }
            else
            {
                rfeatap->mcs_fixedrate_id=869;
            }

            DPRINT_INFO("-->GI = %s \r\n", str);
            DPRINT_INFO("-->MCS ID = %d \r\n", rfeatap->mcs_fixedrate_id);
        }
        //Trigger_TxBF

        //TriggerType

        //ACKType (M-BA)

        //PPDUTxType

        //DisableTriggerType

        //AckPolicy
    }
    DPRINT_CONTENT("***********************************************************\r\n");

    WFA_ENC_TLV(WFA_AP_SET_RFEATURE_TLV, sizeof(caApRFeat_t), (BYTE *)rfeatap, aBuf);
    *aLen = 4+sizeof(caApRFeat_t);

    DPRINT_OUT_FUNC();

    return WFA_SUCCESS;
}
